import React, { useEffect, useState } from 'react';
import {
  ArrowLeft,
  CirclePlus,
  CircleEllipsis,
  Mail,
  MessageCircle,
  Facebook,
  Heart,
  Instagram,
  MessageSquareMore,
  PencilLine,
  Share2,
  UserRound,
  X
} from 'lucide-react';
import styles from './Profile.module.scss';

const FRIENDS = [
  { name: 'Eddie Lobanovskiy', email: 'laboanovskiy@gmail.com' },
  { name: 'Alexey Stave', email: 'alexeyts@gmail.com' },
  { name: 'Anton Tkacheve', email: 'tkacheveanton@gmail.com' },
  { name: 'Maria Gonzalez', email: 'maria.gonzalez@email.com' },
  { name: 'Jin Park', email: 'jin.park@email.com' },
  { name: 'Liam O\'Brien', email: 'liam.obrien@email.com' },
  { name: 'Aisha Khan', email: 'aisha.khan@email.com' },
  { name: 'Ravi Patel', email: 'ravi.patel@email.com' },
  { name: 'Sofia Rossi', email: 'sofia.rossi@email.com' },
  { name: 'David Kim', email: 'david.kim@email.com' }
];

const POSTS = [
  {
    id: 1,
    author: 'Charles Deo',
    time: '15 мин',
    text: 'Нов пост за класически стил, културна памет и съвременно присъствие в мрежата.',
    image: 'https://images.unsplash.com/photo-1516251193007-45ef944ab0c6?auto=format&fit=crop&w=1200&q=80',
    likes: 1498,
    shares: 1498,
    comments: 50
  },
  {
    id: 2,
    author: 'Charles Deo',
    time: '1 ч',
    text: 'Архитектурата на един профил не е само визия, а начин да подредиш какво искаш да казваш.',
    image: null,
    likes: 948,
    shares: 214,
    comments: 31
  }
];

const TAGGED_POSTS = [
  {
    id: 3,
    author: 'Maria Gonzalez',
    time: '3 ч',
    text: 'Тагнах Charles Deo в разговор за естетика, визуална култура и модерна идентичност.',
    image: 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80',
    likes: 302,
    shares: 46,
    comments: 18
  }
];

const THEMES = [
  {
    name: 'Пясък',
    surface: '#e9dfcf',
    accent: '#d9c6a6',
    accentStrong: '#c1a270',
    coverBlend: 'linear-gradient(135deg, rgba(70, 36, 16, 0.16), rgba(70, 36, 16, 0.42))'
  },
  {
    name: 'Маслина',
    surface: '#e3e3d7',
    accent: '#c8ccb2',
    accentStrong: '#8a9770',
    coverBlend: 'linear-gradient(135deg, rgba(44, 58, 32, 0.18), rgba(44, 58, 32, 0.44))'
  },
  {
    name: 'Камък',
    surface: '#e4e1dd',
    accent: '#d1cbc3',
    accentStrong: '#8e8173',
    coverBlend: 'linear-gradient(135deg, rgba(49, 42, 36, 0.14), rgba(49, 42, 36, 0.42))'
  }
];

const PROFILE_STORAGE_KEY = 'filia-profile-draft';

const DEFAULT_PROFILE = {
  name: 'Charles Deo',
  handle: '@Charles_deo',
  email: 'charles5182@ummoh.com',
  bio:
    'Това е примерен текст за биография. Тук може да добавиш кратко представяне, интереси, линкове към социални мрежи и всичко важно за профила.',
  socials: {
    facebook: 'Facebook',
    discord: 'Discord',
    instagram: 'Instagram'
  }
};

export default function Profile({ onNavigate }) {
  const [activeTab, setActiveTab] = useState('posts');
  const [profile, setProfile] = useState(DEFAULT_PROFILE);
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [draft, setDraft] = useState(DEFAULT_PROFILE);
  const [themeIndex] = useState(0);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(PROFILE_STORAGE_KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw);
      setProfile((current) => ({
        ...current,
        ...parsed,
        socials: {
          ...current.socials,
          ...(parsed?.socials || {})
        }
      }));
    } catch (error) {
      // Ignore invalid local profile drafts.
    }
  }, []);

  useEffect(() => {
    window.localStorage.setItem(PROFILE_STORAGE_KEY, JSON.stringify(profile));
  }, [profile]);

  const theme = THEMES[themeIndex];
  const activePosts = activeTab === 'posts' ? POSTS : TAGGED_POSTS;

  const openEditModal = () => {
    setDraft(profile);
    setIsEditOpen(true);
  };

  const closeEditModal = () => {
    setIsEditOpen(false);
    setDraft(profile);
  };

  const handleDraftChange = (field) => (event) => {
    const value = event.target.value;
    setDraft((current) => ({
      ...current,
      [field]: value
    }));
  };

  const handleSocialChange = (field) => (event) => {
    const value = event.target.value;
    setDraft((current) => ({
      ...current,
      socials: {
        ...current.socials,
        [field]: value
      }
    }));
  };

  const saveProfile = (event) => {
    event.preventDefault();
    setProfile({
      ...draft,
      name: draft.name.trim() || DEFAULT_PROFILE.name,
      handle: draft.handle.trim() || DEFAULT_PROFILE.handle,
      email: draft.email.trim() || DEFAULT_PROFILE.email,
      bio: draft.bio.trim() || DEFAULT_PROFILE.bio,
      socials: {
        facebook: draft.socials.facebook.trim() || DEFAULT_PROFILE.socials.facebook,
        discord: draft.socials.discord.trim() || DEFAULT_PROFILE.socials.discord,
        instagram: draft.socials.instagram.trim() || DEFAULT_PROFILE.socials.instagram
      }
    });
    setIsEditOpen(false);
  };

  return (
    <main
      className={styles.page}
      style={{
        '--profile-surface': theme.surface,
        '--profile-accent': theme.accent,
        '--profile-accent-strong': theme.accentStrong,
        '--profile-cover-blend': theme.coverBlend
      }}
    >
      <div className={styles.shell}>
        <section className={styles.heroCard}>
          <div className={styles.heroTopBar}>
            <button type="button" className={styles.backButton} onClick={() => onNavigate?.('posts')}>
              <ArrowLeft size={28} />
            </button>
            <h1>{profile.name}</h1>
          </div>

          <div className={styles.cover} />

          <div className={styles.profileRow}>
            <div className={styles.identityBlock}>
              <div className={styles.avatar}>
                <UserRound size={74} />
              </div>
              <div>
                <h2>{profile.name}</h2>
                <p>{profile.handle}</p>
              </div>
            </div>

            <div className={styles.heroActions}>
              <button type="button" className={styles.actionButton}>
                <CirclePlus size={22} />
                Добави приятел
              </button>
              <button type="button" className={styles.actionButton} onClick={openEditModal}>
                <PencilLine size={20} />
                Редактирай профил
              </button>
            </div>
          </div>
        </section>

        <section className={styles.grid}>
          <aside className={styles.aboutCard}>
            <h3>Информация</h3>
            <div className={styles.infoList}>
              <div className={styles.infoItem}>
                <Mail size={24} />
                <span>{profile.email}</span>
              </div>
              {[
                { key: 'facebook', icon: Facebook },
                { key: 'discord', icon: MessageSquareMore },
                { key: 'instagram', icon: Instagram }
              ].map((item) => {
                const Icon = item.icon;
                return (
                  <div key={item.key} className={styles.infoItem}>
                    <Icon size={24} />
                    <span>{profile.socials[item.key]}</span>
                  </div>
                );
              })}
            </div>

            <div className={styles.bioBlock}>
              <div className={styles.bioHeader}>
                <h3>Биография</h3>
              </div>
              <p>{profile.bio}</p>
            </div>
          </aside>

          <section className={styles.postsCard}>
            <div className={styles.tabs}>
              <button
                type="button"
                className={activeTab === 'posts' ? `${styles.tab} ${styles.tabActive}` : styles.tab}
                onClick={() => setActiveTab('posts')}
              >
                Постове
              </button>
              <span>|</span>
              <button
                type="button"
                className={activeTab === 'tagged' ? `${styles.tab} ${styles.tabActive}` : styles.tab}
                onClick={() => setActiveTab('tagged')}
              >
                Тагнати в постове
              </button>
            </div>

            <div className={styles.postsFeed}>
              {activePosts.map((post) => (
                <article key={post.id} className={styles.post}>
                  <div className={styles.postHeader}>
                    <div className={styles.postAvatar}>
                      <UserRound size={30} />
                    </div>
                    <div>
                      <strong>{post.author}</strong>
                      <span>{post.time}</span>
                    </div>
                    <button type="button" className={styles.moreButton}>
                      <CircleEllipsis size={20} />
                    </button>
                  </div>

                  <p className={styles.postText}>{post.text}</p>
                  {post.image ? (
                    <img src={post.image} alt={post.author} className={styles.postImage} />
                  ) : null}

                  <div className={styles.postStats}>
                    <span><Heart size={22} /> {post.likes.toLocaleString()}</span>
                    <span><Share2 size={22} /> {post.shares.toLocaleString()}</span>
                    <span><MessageCircle size={22} /> {post.comments}</span>
                  </div>

                  <button type="button" className={styles.seeMore}>Виж още</button>
                </article>
              ))}
            </div>
          </section>

          <aside className={styles.friendsCard}>
            <h3>Приятели</h3>
            <div className={styles.friendList}>
              {FRIENDS.map((friend) => (
                <div key={friend.email} className={styles.friendItem}>
                  <div className={styles.friendAvatar}>
                    <UserRound size={22} />
                  </div>
                  <div>
                    <strong>{friend.name}</strong>
                    <span>{friend.email}</span>
                  </div>
                </div>
              ))}
            </div>
          </aside>
        </section>
      </div>

      {isEditOpen ? (
        <div className={styles.modalOverlay} onClick={closeEditModal} role="presentation">
          <section
            className={styles.modalCard}
            onClick={(event) => event.stopPropagation()}
            role="dialog"
            aria-modal="true"
            aria-labelledby="edit-profile-title"
          >
            <div className={styles.modalHeader}>
              <div>
                <p className={styles.modalEyebrow}>Редакция на профил</p>
                <h2 id="edit-profile-title">Редактирай профила</h2>
              </div>
              <button type="button" className={styles.iconButton} onClick={closeEditModal} aria-label="Затвори редакцията">
                <X size={20} />
              </button>
            </div>

            <form className={styles.editForm} onSubmit={saveProfile}>
              <div className={styles.formGrid}>
                <label className={styles.field}>
                  <span>Име</span>
                  <input value={draft.name} onChange={handleDraftChange('name')} />
                </label>
                <label className={styles.field}>
                  <span>Потребителско име</span>
                  <input value={draft.handle} onChange={handleDraftChange('handle')} />
                </label>
                <label className={styles.field}>
                  <span>Имейл</span>
                  <input type="email" value={draft.email} onChange={handleDraftChange('email')} />
                </label>
                <label className={styles.field}>
                  <span>Facebook</span>
                  <input value={draft.socials.facebook} onChange={handleSocialChange('facebook')} />
                </label>
                <label className={styles.field}>
                  <span>Discord</span>
                  <input value={draft.socials.discord} onChange={handleSocialChange('discord')} />
                </label>
                <label className={styles.field}>
                  <span>Instagram</span>
                  <input value={draft.socials.instagram} onChange={handleSocialChange('instagram')} />
                </label>
              </div>

              <label className={`${styles.field} ${styles.fieldFull}`}>
                <span>Биография</span>
                <textarea rows="6" value={draft.bio} onChange={handleDraftChange('bio')} />
              </label>

              <div className={styles.modalActions}>
                <button type="button" className={styles.secondaryButton} onClick={closeEditModal}>
                  Отказ
                </button>
                <button type="submit" className={styles.primaryButton}>
                  Запази промените
                </button>
              </div>
            </form>
          </section>
        </div>
      ) : null}
    </main>
  );
}
